    static class Stats {
        public static readonly int[] Modes={11,12,21,22};
        public static string Label(int mode){return mode==0?"全部模式":mode==11?"1v1 匹配":mode==12?"1v1 天梯":mode==21?"2v2 匹配":"2v2 天梯";}
        static object Official(Snapshot s,int mode){return mode==12||mode==22?J.Get(s.OfficialSummary,mode==12?"T1":"T2"):null;}
        public static int? OfficialCount(Snapshot s,int mode){try{object value=J.Get(Official(s,mode),"TotalCnt");if(value==null)return null;long n=J.Num(value);return n>=0&&n<=int.MaxValue?(int?)n:null;}catch{return null;}}
        public static string Coverage(Snapshot s,int mode){
            if(s.IsAggregate)return "按账号记录累计，共 "+s.Battles.Count(b=>mode==0||b.Mode==mode)+" 场；同一局在不同账号中分别计数。"+string.Join(" ",s.ViewSources.Select(x=>x.Name+" / "+x.SeasonName+" / "+x.GameCode+"："+Coverage(x,mode)));if(mode==0)return "四模式实际记录合计 "+s.Battles.Count+" 场。"+string.Join(" ",Modes.Select(m=>Coverage(s,m)));int? official=OfficialCount(s,mode);int count=s.Battles.Count(b=>(mode==0||b.Mode==mode));if(!official.HasValue)return "仅统计已取得的逐场记录；未取得此模式的可核对汇总。";
            string gap=count<official.Value?"，缺少 "+(official.Value-count)+" 场":count>official.Value?"，比汇总多 "+(count-official.Value)+" 场":"，场数一致";
            double rate;string win=double.TryParse(J.Str(Official(s,mode),"WinRate"),NumberStyles.Float,CultureInfo.InvariantCulture,out rate)&&rate>=0&&rate<=1?" / 胜率 "+(rate*100).ToString("0.00")+"%":"";
            return Label(mode)+"：官网 "+official.Value+" 场"+win+"；已取得 "+count+" 场"+gap+"。";
        }
        public static bool CoverageMismatch(Snapshot s,int mode){
            if(s.IsAggregate)return s.ViewSources.Any(x=>CoverageMismatch(x,mode));if(mode==0)return Modes.Any(m=>CoverageMismatch(s,m));int? official=OfficialCount(s,mode);if(!official.HasValue)return false;var rows=s.Battles.Where(b=>(mode==0||b.Mode==mode)).ToList();if(rows.Count!=official.Value)return true;
            double rate;return rows.Count>0&&double.TryParse(J.Str(Official(s,mode),"WinRate"),NumberStyles.Float,CultureInfo.InvariantCulture,out rate)&&rate>=0&&rate<=1&&Math.Abs((double)rows.Count(b=>b.Result=="win")/rows.Count-rate)>0.000051;
        }
        public static List<Pair> Pairs(Snapshot s,int mode){var map=new Dictionary<string,Pair>();foreach(var b in s.Battles.Where(b=>(mode==0||b.Mode==mode)&&b.DetailStatus=="ok"))foreach(var mine in b.MyRoles.GroupBy(r=>r.Id).Select(g=>g.First()))foreach(var enemy in b.EnemyRoles.GroupBy(r=>r.Id).Select(g=>g.First())){string key=J.Json.Serialize(new[]{mine.Id,enemy.Id});Pair p;if(!map.TryGetValue(key,out p)){p=new Pair{Mine=mine,Enemy=enemy};map[key]=p;}p.Games++;if(b.Result=="win")p.Wins++;}return map.Values.OrderByDescending(p=>p.Games).ThenBy(p=>p.Mine.Name).ToList();}
        public static bool HasTeam(Battle b){return b.Mode>20&&b.TeamDetailStatus=="ok"&&b.MyTeamRoles.Count==2&&b.EnemyTeamRoles.Count==2;}
        public static string TeamName(IEnumerable<Role> roles){return string.Join(" + ",roles.OrderBy(r=>r.Id,StringComparer.Ordinal).Select(r=>r.Name));}
        public static string MateKey(Battle b){return J.Json.Serialize(new[]{b.ViewGameCode??"",string.IsNullOrWhiteSpace(b.AllyUid)?"name":"uid",string.IsNullOrWhiteSpace(b.AllyUid)?b.AllyName:b.AllyUid});}public static bool MatchesMate(Battle b,string filter){return string.IsNullOrEmpty(filter)||(filter.StartsWith("@mate:")?MateKey(b)==filter.Substring(6):b.AllyUid==filter||b.AllyName==filter);}public static List<Battle> TeamBattles(Snapshot s,int mode,string mine="",string ally="",string uid=""){
            return s.Battles.Where(b=>(mode==0||b.Mode==mode)&&HasTeam(b)&&(mine==""||b.MyRoles.Any(r=>r.Id==mine))&&(ally==""||b.AllyRoles.Any(r=>r.Id==ally))&&MatchesMate(b,uid)).ToList();
        }
        public static List<TeamPair> Teams(Snapshot s,int mode,bool versus,string mine="",string ally="",string uid=""){
            var map=new Dictionary<string,TeamPair>();foreach(var b in TeamBattles(s,mode,mine,ally,uid)){
                var own=b.MyTeamRoles.OrderBy(r=>r.Id,StringComparer.Ordinal).ToList();var enemy=versus?b.EnemyTeamRoles.OrderBy(r=>r.Id,StringComparer.Ordinal).ToList():new List<Role>();
                string key=J.Json.Serialize(new[]{own.Select(r=>r.Id).ToArray(),enemy.Select(r=>r.Id).ToArray()});TeamPair p;
                if(!map.TryGetValue(key,out p)){p=new TeamPair{Mine=own,Enemy=enemy};map[key]=p;}p.Games++;if(b.Result=="win")p.Wins++;
            }return map.Values.OrderByDescending(p=>p.Games).ThenBy(p=>TeamName(p.Mine)).ThenBy(p=>TeamName(p.Enemy)).ToList();
        }
        public static List<Teammate> Teammates(Snapshot s,int mode,string uid=""){
            return s.Battles.Where(b=>(mode==0||b.Mode==mode)&&b.Mode>20&&b.DetailStatus=="ok"&&(!string.IsNullOrWhiteSpace(b.AllyUid)||!string.IsNullOrWhiteSpace(b.AllyName))&&MatchesMate(b,uid)).GroupBy(MateKey).Select(g=>new Teammate{Identity=g.Key,GameCode=g.First().ViewGameCode,Uid=g.First().AllyUid??"",Basis=!string.IsNullOrWhiteSpace(g.First().AllyUid)?"UID":"昵称",Name=g.OrderByDescending(b=>b.Start).Select(b=>b.AllyName).FirstOrDefault(n=>!string.IsNullOrWhiteSpace(n))??"未知昵称",Games=g.Count(),Wins=g.Count(b=>b.Result=="win"),RoleRows=g.SelectMany(b=>b.AllyRoles.Select(r=>new{Role=r,Win=b.Result=="win"})).GroupBy(x=>x.Role.Id).OrderByDescending(x=>x.Count()).Select(x=>new TeammateRole{Role=x.First().Role,Games=x.Count(),Wins=x.Count(y=>y.Win)}).ToList(),Roles=string.Join("；",g.SelectMany(b=>b.AllyRoles.Select(r=>new{Role=r,Win=b.Result=="win",Battle=b})).GroupBy(x=>x.Role.Id).OrderByDescending(x=>x.Count()).Select(x=>x.First().Role.Name+" "+x.Count()+" 场 / "+(100.0*x.Count(y=>y.Win)/x.Count()).ToString("0.0")+"%"))}).OrderByDescending(t=>t.Games).ThenBy(t=>t.Uid).ToList();
        }
        public static List<Snapshot> DecodeMany(string path){if(new FileInfo(path).Length>64*1024*1024)throw new Exception("数据文件超过 64 MB");string text=File.ReadAllText(path);if(J.Str(J.Json.DeserializeObject(text),"Format")!="XZY-BattleArchive")return new List<Snapshot>{Decode(path)};var archive=J.Json.Deserialize<SnapshotArchive>(text);if(archive.Version!=1||archive.Snapshots==null||archive.Snapshots.Count>500)throw new Exception("备份格式无效");foreach(var s in archive.Snapshots){Storage.Upgrade(s);Storage.Validate(s);Merge.Key(s);}return archive.Snapshots;}
        public static Snapshot Decode(string path){
            if(new FileInfo(path).Length>64*1024*1024)throw new Exception("数据文件超过 64 MB。");var obj=J.Json.DeserializeObject(File.ReadAllText(path));if(J.Str(obj,"Format")=="XZY-BattleStats")return Storage.Load(path);
            if(J.Str(obj,"Format")!="XZY-RawBattleStats"||(int)J.Number(obj,"Version",0)!=1)throw new Exception("请选择官网导出助手或本程序导出的战绩 JSON。");
            var s=new Snapshot{Uid=J.Str(obj,"Uid"),Name=J.Str(obj,"Name"),GameCode=J.Str(obj,"GameCode"),SeasonCode=(int)J.Number(obj,"SeasonCode",0),SeasonName=J.Str(obj,"SeasonName"),SeasonStart=J.Number(obj,"SeasonStart",0),SeasonEnd=J.Number(obj,"SeasonEnd",0),DataAsOf=J.Number(obj,"DataAsOf",0),ListComplete=J.Bool(J.Get(obj,"ListComplete")),OfficialSummary=J.Get(obj,"OfficialSummary"),ListAudit=J.Get(obj,"ListAudit")};
            if(J.Get(obj,"Warnings")!=null)s.Warnings=J.List(J.Get(obj,"Warnings")).Select(J.Text).ToList();var catalog=new Dictionary<string,Role>();Parse.Catalog(J.Get(obj,"Roles"),catalog,0);
            foreach(var match in J.List(J.Get(obj,"Matches"))){var b=Parse.Row(J.Get(match,"Row"));try{if(J.Get(match,"Detail")==null)throw new Exception(J.Str(match,"Error")==""?"官网未返回详情。":J.Str(match,"Error"));Parse.Detail(b,J.Get(match,"Detail"),s.Uid,s.Name,catalog);}catch(Exception ex){b.DetailStatus="error";b.DetailError=ex.Message;}s.Battles.Add(b);}
            int missing=s.Battles.Count(b=>b.DetailStatus!="ok");if(missing>0)s.Warnings.Add(missing+" 场详情未取得或无法识别本人；总战绩包含这些场次，个人对位表不包含。完整双方阵容仍可纳入队伍组合表。重新导出可重试。");Storage.Validate(s);return s;
        }
        static string Quote(string s){if(s==null)s="";if(s.Length>0&&"=+-@\t\r".Contains(s[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}
        public static string Csv(Snapshot s,bool aggregate=false){var lines=new List<string>{"模式,我方角色,敌方阵容角色,样本场数,胜场,负场,胜率,口径,赛季,数据范围核对"};foreach(int mode in aggregate?new[]{0}:Modes)foreach(var p in Pairs(s,mode))lines.Add(string.Join(",",new[]{Quote(Label(mode)),Quote(p.Mine.Name),Quote(p.Enemy.Name),p.Games.ToString(),p.Wins.ToString(),(p.Games-p.Wins).ToString(),(100.0*p.Wins/p.Games).ToString("0.00",CultureInfo.InvariantCulture)+"%",Quote(mode<20?"双方出战阵容角色共同出现的整场结果":"本人角色与敌方阵容角色共同出现的整场结果"),Quote(s.SeasonName),Quote(Coverage(s,mode))}));return string.Join("\r\n",lines);}
        public static string TeamCsv(Snapshot s,bool aggregate=false){var lines=new List<string>{"模式,统计类型,我方组合,敌方组合,样本场数,胜场,负场,胜率,赛季,数据范围核对"};foreach(int m in aggregate?new[]{0}:new[]{21,22})foreach(bool versus in new[]{false,true})foreach(var p in Teams(s,m,versus))lines.Add(string.Join(",",new[]{Quote(Label(m)),Quote(versus?"组合对位":"组合表现"),Quote(TeamName(p.Mine)),Quote(TeamName(p.Enemy)),p.Games.ToString(),p.Wins.ToString(),(p.Games-p.Wins).ToString(),(100.0*p.Wins/p.Games).ToString("0.00",CultureInfo.InvariantCulture)+"%",Quote(s.SeasonName),Quote(Coverage(s,m))}));return string.Join("\r\n",lines);}
        public static string TeammateCsv(Snapshot s,bool aggregate=false){var lines=new List<string>{"模式,队友昵称,共同场数,胜场,负场,胜率,队友角色场数与胜率,赛季,数据范围核对"};foreach(int m in aggregate?new[]{0}:new[]{21,22})foreach(var t in Teammates(s,m))lines.Add(string.Join(",",new[]{Quote(Label(m)),Quote(t.Name),t.Games.ToString(),t.Wins.ToString(),(t.Games-t.Wins).ToString(),(100.0*t.Wins/t.Games).ToString("0.00",CultureInfo.InvariantCulture)+"%",Quote(t.Roles),Quote(s.SeasonName),Quote(Coverage(s,m))}));return string.Join("\r\n",lines);}
    }
