        static string Chosen(ComboBox box){return box.SelectedItem is Choice?((Choice)box.SelectedItem).Id:"";}
        static void FillChoices(ComboBox box,IEnumerable<Role> source){string selected=Chosen(box);box.Items.Clear();box.Items.Add(new Choice{Id="",Name="全部角色"});foreach(var r in source.GroupBy(r=>r.Id).Select(g=>g.First()).OrderBy(r=>r.Name))box.Items.Add(new Choice{Id=r.Id,Name=r.Name});box.SelectedIndex=0;for(int i=0;i<box.Items.Count;i++)if(((Choice)box.Items[i]).Id==selected)box.SelectedIndex=i;}
        static DataTable ResultsTable(string first,string second){var table=new DataTable();table.Columns.Add(first);if(second!="")table.Columns.Add(second);foreach(string c in new[]{"场次","胜","负"})table.Columns.Add(c,typeof(int));table.Columns.Add("胜率",typeof(double));return table;}
        void RenderTeams(){DataTable overall=ResultsTable("我方组合",""),versus=ResultsTable("我方组合","敌方组合");bool active=data!=null&&(mode==0||mode>20);teamMine.Enabled=teamAlly.Enabled=teamUid.Enabled=teamMinimum.Enabled=active;
            if(active){string own=Chosen(teamMine),ally=Chosen(teamAlly),uid=Chosen(teamUid);foreach(bool v in new[]{false,true})foreach(var p in Stats.Teams(data,mode,v,own,ally,uid).Where(p=>p.Games>=teamMinimum.Value)){var values=new List<object>{Stats.TeamName(p.Mine)};if(v)values.Add(Stats.TeamName(p.Enemy));values.AddRange(new object[]{p.Games,p.Wins,p.Games-p.Wins,100.0*p.Wins/p.Games});(v?versus:overall).Rows.Add(values.ToArray());}int total=data.Battles.Count(b=>(mode==0||b.Mode==mode)),valid=data.Battles.Count(b=>(mode==0||b.Mode==mode)&&Stats.HasTeam(b)),filtered=Stats.TeamBattles(data,mode,own,ally,uid).Count;teamScope.Text="双方组合完整："+valid+" / "+total+" 场；筛选命中 "+filtered+" 场。两人顺序合并；相同角色双人组合保留。";}else teamScope.Text="请选择 2v2 匹配或 2v2 天梯并导入战绩；队伍组合统计不用于 1v1。";BindSorted(teamOverall,overall,"场次");BindSorted(teamPairs,versus,"场次");
