        Teammate SelectedMate(){var row=teammates.CurrentRow;if(row==null||mateSourceTable==null)return null;var view=row.DataBoundItem as DataRowView;if(view==null||view.Row.Table!=mateSourceTable)return null;int index=mateSourceTable.Rows.IndexOf(view.Row);return index>=0&&index<mateDisplayRows.Count?mateDisplayRows[index]:null;}
