            if(active){displayed=Stats.Teammates(data,mode,mateUid.Text.Trim());foreach(var t in displayed)table.Rows.Add(t.Name,t.Games,t.Wins,t.Games-t.Wins,100.0*t.Wins/t.Games);int known=Stats.Teammates(data,mode).Sum(t=>t.Games),total=data.Battles.Count(b=>(mode==0||b.Mode==mode));mateScope.Text="队友记录："+known+" / "+total+" 场。";}else mateScope.Text="请选择 2v2 匹配或 2v2 天梯；这里统计你与各队友共同参加的对局。";
