    static class NativeProgram {
        [STAThread]static void Main(string[] args){try{if(args.Length>2&&args[0]=="--verify"){var s=Stats.Decode(args[1]);if(s.Battles.Count!=16||s.Battles.Any(b=>b.DetailStatus!="ok"))throw new Exception("Fixture details incomplete");foreach(int m in Stats.Modes){if(s.Battles.Count(b=>b.Mode==m)!=4)throw new Exception("Mode isolation failed");var ps=Stats.Pairs(s,m);if(ps.Any(p=>p.Games!=4))throw new Exception("Pair deduplication failed");if(m>20&&(ps.Count!=1||ps[0].Mine.Id!="1"||ps[0].Enemy.Id!="4"))throw new Exception("Ally exclusion failed");}Storage.Save(args[2],s);File.WriteAllText(args[2]+".passed.txt","PASS: raw official-schema import, 16 battles, 4 independent modes, second-position self, ally exclusion, duplicate opponent counted once, all details recognized");return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool isPreview=args.Length>2&&args[0]=="--preview";using(var f=new NativeForm(isPreview,isPreview?args[1]:null,isPreview?args[2]:null)){if(isPreview){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-32000,-32000);f.ShowInTaskbar=false;}Application.Run(f);}}catch(Exception ex){if(args.Length>1)File.WriteAllText(args[1]+".error.txt",ex.ToString());else MessageBox.Show(ex.Message,"星之翼战绩统计");}}
